PROGRAM alarm_ctrl
VAR_INPUT
    Trip : BOOL;
    Reset : BOOL;
END_VAR
VAR_OUTPUT
    Alarm : BOOL;
END_VAR
VAR
    Alarm_Latch : BOOL;
END_VAR

Alarm_Latch := FALSE;

IF Trip THEN
    Alarm_Latch := TRUE;
ELSIF Reset AND NOT Trip THEN
    Alarm_Latch := FALSE;
END_IF;

Alarm := Alarm_Latch;
END_PROGRAM

