PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR
    State : INT;
    LIQ_MIN : CONST INT := 10;
    LVL_HIGH : CONST INT := 80;
    LVL_LOW : CONST INT := 5;
    TEMP_SET : CONST INT := 100;
    PT_REACT : CONST TIME := T#3s;
END_VAR
VAR CONSTANT
    TON : STRUCT
        IN : BOOL;
        PT : TIME;
        Q : BOOL;
    END_STRUCT;
VAR CONSTANT
    Timer : TON;
END_VAR

IF EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND Level >= LIQ_MIN THEN
    CASE State OF
        0:
            IF Level < LVL_HIGH THEN
                State := 1;
                FillValve := TRUE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        1:
            IF Level >= LVL_HIGH THEN
                State := 2;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        2:
            IF Temp >= TEMP_SET THEN
                State := 3;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        3:
            IF NOT Timer.Q THEN
                Timer(IN := TRUE, PT := PT_REACT);
            ELSE
                State := 4;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := FALSE;
            END_IF;
        4:
            IF Level <= LVL_LOW THEN
                State := 0;
                FillValve := FALSE;
                Heater := FALSE;
                Agitator := FALSE;
                DrainValve := FALSE;
            ELSE
                State := 4;
                FillValve := FALSE;
                Heater := TRUE;
                Agitator := TRUE;
                DrainValve := TRUE;
            END_IF;
    END_CASE;
END_IF;

IF State = 1 OR State = 4 THEN
    FillValve := TRUE;
    DrainValve := FALSE;
ELSE
    FillValve := FALSE;
END_IF;

IF State = 2 OR State = 3 THEN
    Heater := TRUE;
    Agitator := TRUE;
ELSE
    Heater := FALSE;
    Agitator := FALSE;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
