    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
ELSIF StartBatch AND State = 0 THEN
    State := 1;
ELSIF (State = 1 AND Level >= LVL_HIGH) OR (State = 2 AND Temp >= TEMP_SET) OR (State = 3 AND NOT PT_REACT.TON()) OR (State = 4 AND Level <= LVL_LOW) THEN
    State := State + 1;

CASE State OF
    0:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    1:
        FillValve := TRUE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := FALSE;
    2:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
    3:
        FillValve := FALSE;
        Heater := TRUE;
        Agitator := TRUE;
        DrainValve := FALSE;
        PT_REACT(IN := TRUE, PT := PT_REACT);
    4:
        FillValve := FALSE;
        Heater := FALSE;
        Agitator := FALSE;
        DrainValve := TRUE;
    ELSE
        State := 0;
END_CASE;

IF State = 1 AND Level < LIQ_MIN THEN
    State := 0;
ELSIF State = 4 AND DrainValve AND FillValve THEN
    State := 0;
END_IF;

END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR_INPUT
    StartBatch : BOOL;
    Level : INT;
    Temp : INT;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    FillValve : BOOL;
    Heater : BOOL;
    Agitator : BOOL;
    DrainValve : BOOL;
END_VAR
VAR_CONSTANT
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    LIQ_MIN : INT := 10;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
END_VAR
VAR
    State : INT := 0;
END_VAR
TON T1(PT := PT_REACT);

CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
        END_IF;

    1: // Fill
        FillValve := TRUE;
        IF Level >= LVL_HIGH OR NOT EStop THEN
            FillValve := FALSE;
            State := 2;
        END_IF;

    2: // Heat
        Heater := TRUE;
        Agitator := TRUE;
        IF Temp >= TEMP_SET OR NOT EStop THEN
            State := 3;
        END_IF;

    3: // React
        Heater := TRUE;
        Agitator := TRUE;
        IF NOT EStop THEN
            IF T1.Q THEN
                State := 4;
            END_IF;
        END_IF;

    4: // Drain
        DrainValve := TRUE;
        IF Level <= LVL_LOW OR NOT EStop THEN
            DrainValve := FALSE;
            State := 0;
        END_IF;
END_CASE;

// Safety conditions
FillValve := FillValve AND NOT DrainValve;
Heater := Heater AND (Level >= LIQ_MIN);
Agitator := Agitator AND (Level >= LIQ_MIN);
END_PROGRAM

