            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
        END_IF;
    3: -- React
        IF Temp >= TEMP_SET AND T1.Q THEN
            State := 4;
        ELSE
            FillValve := FALSE;
            Heater := TRUE;
            Agitator := TRUE;
            DrainValve := FALSE;
            T1(IN := TRUE, PT := PT_REACT);
        END_IF;
    4: -- Drain
        IF Level <= LVL_LOW OR NOT EStop THEN
            State := 0;
        ELSE
            FillValve := FALSE;
            Heater := FALSE;
            Agitator := FALSE;
            DrainValve := TRUE;
        END_IF;
END_CASE;

IF EStop THEN
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
