PROGRAM tank_cycle
VAR_INPUT
    Level : INT;
    StartCycle : BOOL;
    EStop : BOOL;
END_VAR
VAR_OUTPUT
    Pump : BOOL;
    Valve : BOOL;
END_VAR
VAR
    State : INT := 0;
END_VAR

IF NOT EStop THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
ELSIF State = 0 AND StartCycle AND Level < 90 THEN
    State := 1;
    Pump := TRUE;
    Valve := FALSE;
ELSIF State = 1 AND Level >= 90 THEN
    State := 2;
    Pump := FALSE;
    Valve := TRUE;
ELSIF State = 2 AND Level <= 10 THEN
    State := 0;
    Pump := FALSE;
    Valve := FALSE;
END_IF;

CASE State OF
    0: // Idle
        Pump := FALSE;
        Valve := FALSE;
    1: // Filling
        Pump := TRUE;
        Valve := FALSE;
    2: // Draining
        Pump := FALSE;
        Valve := TRUE;
END_CASE;

// Safety conditions
ASSERT(not (Pump and Valve));
ASSERT(Level < 90 or not Pump);
ASSERT(Level > 10 or not Valve);

END_PROGRAM

