    C3 : BOOL;
END_VAR
VAR
    State : INT;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB AND NOT StopPB THEN
                State := 1;
                T_C3(IN := TRUE, PT := T#2s);
            END_IF;
        1:
            IF T_C3.Q THEN
                State := 2;
                T_C2(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF T_C2.Q THEN
                State := 3;
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
            END_IF;
        3:
            IF StopPB OR NOT EStop THEN
                State := 0;
                C1 := FALSE;
                C2 := FALSE;
                C3 := FALSE;
            END_IF;
    END_CASE;
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
END_IF;

